    /**
     * Produces records consumed by existing Learn/live renderers only after both gates pass.
     * No generic or English-fallback strings are permitted here.
     */
    fun runtimeAssets(
        localizations: P1ExactInstructionAssetLocalizationCatalog =
            P1ExactInstructionAssetLocalizations.production,
        localizationCoverage: P1ExactRecipeLocalizationCoverage =
            P1ExactRecipeLocalizationCoverage.production,
    ): List<InstructionAssetRecord> = assets.mapNotNull { candidate ->
        val localization = localizations.find(candidate.id) ?: return@mapNotNull null
        if (!localizationCoverage.isComplete(candidate.recipeId)) return@mapNotNull null
        candidate.toRuntimeAsset(localization)
    }

    private fun P1TrackerAcceptedInstructionAsset.toRuntimeAsset(
        localization: P1ExactInstructionAssetLocalization,
    ): InstructionAssetRecord = InstructionAssetRecord(
        id = id,
        familyId = familyId,
        profileId = profileId,
        stageId = stageId,
        contentId = contentId,
        namingConvention = InstructionAssetNamingConvention.EXACT_CONTENT_ID,
        drawableRes = drawableRes,
        altTextRes = localization.altTextRes,
        companionInstructionRes = localization.companionInstructionRes,
        mandatoryForFullGuidance = visualPriority != P1ExactVisualPriority.OPTIONAL,
        safetySensitive = visualPriority == P1ExactVisualPriority.SAFETY_CRITICAL,
        provenance = InstructionAssetProvenance(
            promptDocument = TRACKER_PATH,
            promptRevision = "accepted_${trackerRevision}",
        ),
        review = localization.runtimeReview,
    )
}
